324	        },
325	        afterUserInput: async () => {
326	          callOrder.push('afterUserInput');
327	        },
328	        beforeModelResponse: async (_s, p) => {
329	          callOrder.push('beforeModelResponse');
330	          return p;
331	        },
332	        afterModelResponse: async () => {
333	          callOrder.push('afterModelResponse');
334	        },
335	        afterSession: async () => {
336	          callOrder.push('afterSession');
337	        },
338	      };
339	
340	      const orchestrator = createChatOrchestrator(createMockProvider('ok', usage), promptBuilder, undefined, {hooks});
341	      await orchestrator.processMessage(createSession('hello'));
342	
343	      expect(callOrder).toEqual([
344	        'beforeSession',
345	        'beforeUserInput',
346	        'afterUserInput',
347	        'beforeModelResponse',
