    expect([silent.chunks.slice(-2), empty.chunks.slice(-2)]).toEqual([
      [{type: 'stop', stopReason: 'tool_use'}, BUDGET_STOP],
      [{type: 'stop', stopReason: 'tool_use'}, BUDGET_STOP],
    ]);
  });

